// -------------------- Canvas hierarchy / UI state --------------------
const CANVAS_WORLD_W=6000, CANVAS_WORLD_H=4000, CANVAS_ZOOM_MIN=.25, CANVAS_ZOOM_MAX=3;
const DEVELOPMENTAL_LANE_START_X=120, DEVELOPMENTAL_LANE_CARD_Y=118, DEVELOPMENTAL_LANE_BOTTOM=286, DEVELOPMENTAL_FREE_Y=390, DEVELOPMENTAL_CARD_GAP=32;
let canvasPanelEpoch=0;

async function restoreCanvasUIState(preloaded=null,{render=true}={}){
  try{let treeValue,railValue,activeValue;if(preloaded){treeValue=preloaded['canvas-tree'];railValue=preloaded['canvas-rail'];activeValue=preloaded['canvas-active']}else{const[tree,rail,active]=await Promise.all([api('/api/ui-state/canvas-tree'),api('/api/ui-state/canvas-rail'),api('/api/ui-state/canvas-active')]);treeValue=tree.value;railValue=rail.value;activeValue=active.value}state.canvasCollapsed=new Set(Array.isArray(treeValue)?treeValue.map(entityId):[]);state.canvasRailExpanded=railValue!==false;const remembered=entityId(activeValue);state.lastCanvasId=isEntityId(remembered)&&state.canvases.some(canvas=>entityId(canvas.id)===remembered)?remembered:null;$('#canvasRail').classList.toggle('collapsed',!state.canvasRailExpanded);if(render)renderCanvasRail()}catch(error){console.warn('Could not restore canvas UI state',error)}
}
function persistCanvasTree(){api('/api/ui-state/canvas-tree',{method:'PUT',body:JSON.stringify({value:[...state.canvasCollapsed]})}).catch(console.warn)}
function persistCanvasRail(){api('/api/ui-state/canvas-rail',{method:'PUT',body:JSON.stringify({value:state.canvasRailExpanded})}).catch(console.warn)}
async function persistActiveCanvas(id){const canvasId=entityId(id);if(!isEntityId(canvasId)||!state.canvases.some(canvas=>entityId(canvas.id)===canvasId))return;state.lastCanvasId=canvasId;await api('/api/ui-state/canvas-active',{method:'PUT',body:JSON.stringify({value:canvasId})})}
$('#toggleRail').onclick=()=>{state.canvasRailExpanded=!state.canvasRailExpanded;$('#canvasRail').classList.toggle('collapsed',!state.canvasRailExpanded);persistCanvasRail()};

let canvasDetailsHoverTimer=null,canvasDetailsHoverSourceId=null;
function hideCanvasDetailsHover(){clearTimeout(canvasDetailsHoverTimer);canvasDetailsHoverTimer=null;canvasDetailsHoverSourceId=null;$('#canvasDetailsHover')?.remove()}
function queueCanvasDetailsHover(canvas,row){
  hideCanvasDetailsHover();if(state.dragCanvasId)return;const details=String(canvas?.description||'').trim();if(!details)return;const id=entityId(canvas.id);canvasDetailsHoverSourceId=id;
  canvasDetailsHoverTimer=setTimeout(()=>{if(canvasDetailsHoverSourceId!==id||!row.isConnected||!row.matches(':hover'))return;const card=document.createElement('div');card.id='canvasDetailsHover';card.className='chapter-details-hover-card canvas-details-hover-card';card.innerHTML=`<div>${escapeHtml(details).replace(/\n/g,'<br>')}</div>`;document.body.appendChild(card);const r=row.getBoundingClientRect(),b=card.getBoundingClientRect(),gap=8,edge=8;let left=r.right+gap;if(left+b.width>innerWidth-edge)left=Math.max(edge,r.left-b.width-gap);const top=Math.max(edge,Math.min(innerHeight-b.height-edge,r.top+(r.height-b.height)/2));card.style.left=`${Math.round(left)}px`;card.style.top=`${Math.round(top)}px`},300)
}
function canvasCollectionMenuItems(){return[{label:'Add Canvas',action:()=>openNewCanvasModal(null)},{label:'Import Canvas…',action:()=>beginJsonImport({view:'canvas',canvas_id:null,fragment_scope:'canvas'})}]}
function openCanvasCollectionMenu(event){event.preventDefault();event.stopPropagation();const items=canvasCollectionMenuItems();if(event.type==='contextmenu')openContextMenu(event.clientX,event.clientY,items);else{const rect=event.currentTarget.getBoundingClientRect();openContextMenu(rect.left,rect.bottom+4,items,{anchorRect:rect})}}
function canvasMenuItems(canvas){return[{label:'New canvas inside…',action:()=>openNewCanvasModal(canvas.id)},{label:'Import JSON…',action:()=>beginJsonImport({view:'canvas',canvas_id:canvas.id})},{label:'Configure…',action:()=>configureCanvas(canvas)},{separator:true},{label:'Delete canvas…',danger:true,action:()=>deleteCanvas(canvas)}]}
function openCanvasMenu(event,canvas){hideCanvasDetailsHover();if(event.type==='contextmenu')openContextMenu(event.clientX,event.clientY,canvasMenuItems(canvas));else{const rect=event.currentTarget.getBoundingClientRect();openContextMenu(rect.left,rect.bottom+4,canvasMenuItems(canvas),{anchorRect:rect})}}
function canvasRailLabel(canvas){return compactRailLabel(canvas?.name,['Canvas','Chapter'])}

function canvasParentKey(canvas){return canvas?.parent_id==null?0:entityId(canvas.parent_id)}
let canvasNestHoverTimer=null,canvasNestHoverId=null,canvasNestReadyId=null;
function clearCanvasNestHover(){clearTimeout(canvasNestHoverTimer);canvasNestHoverTimer=null;canvasNestHoverId=null;canvasNestReadyId=null;document.querySelectorAll('.canvas-item.nest-hover,.canvas-item.nest-ready').forEach(row=>row.classList.remove('nest-hover','nest-ready'))}
function clearCanvasDropIndicator(){document.querySelectorAll('.canvas-item.drop-before,.canvas-item.drop-after').forEach(row=>row.classList.remove('drop-before','drop-after'));clearCanvasNestHover()}
function canvasDescendantIds(canvasId){const descendants=new Set(),queue=[entityId(canvasId)];while(queue.length){const parent=queue.shift();for(const canvas of state.canvases){if(entityId(canvas.parent_id)!==entityId(parent)||descendants.has(entityId(canvas.id)))continue;descendants.add(entityId(canvas.id));queue.push(entityId(canvas.id))}}return descendants}
function canNestCanvas(movingCanvas,targetCanvas){if(!movingCanvas||!targetCanvas||entityId(movingCanvas.id)===entityId(targetCanvas.id)||entityId(movingCanvas.parent_id)===entityId(targetCanvas.id))return false;return !canvasDescendantIds(movingCanvas.id).has(entityId(targetCanvas.id))}
function beginCanvasNestHover(row,movingCanvas,targetCanvas){if(!canNestCanvas(movingCanvas,targetCanvas))return;document.querySelectorAll('.canvas-item.drop-before,.canvas-item.drop-after').forEach(item=>item.classList.remove('drop-before','drop-after'));if(canvasNestReadyId===entityId(targetCanvas.id)){row.classList.add('nest-ready');return}if(canvasNestHoverId===entityId(targetCanvas.id))return;clearCanvasNestHover();canvasNestHoverId=entityId(targetCanvas.id);row.classList.add('nest-hover');canvasNestHoverTimer=setTimeout(()=>{if(state.dragCanvasId!==entityId(movingCanvas.id)||canvasNestHoverId!==entityId(targetCanvas.id)||!row.isConnected)return;canvasNestReadyId=entityId(targetCanvas.id);row.classList.remove('nest-hover');row.classList.add('nest-ready')},550)}
async function moveCanvasToParent(movingCanvas,newParentId,{afterCanvasId=null}={}){
  if(!movingCanvas)return;const normalizedParent=newParentId==null?null:entityId(newParentId);if((movingCanvas.parent_id==null?null:entityId(movingCanvas.parent_id))===normalizedParent)return;
  const siblings=state.canvases.filter(canvas=>(canvas.parent_id==null?null:entityId(canvas.parent_id))===normalizedParent&&entityId(canvas.id)!==entityId(movingCanvas.id)).sort((a,b)=>(+a.position||0)-(+b.position||0)||compareEntityIds(a.id,b.id));let insertAt=siblings.length;if(afterCanvasId!=null){const index=siblings.findIndex(canvas=>entityId(canvas.id)===entityId(afterCanvasId));if(index>=0)insertAt=index+1}const ids=siblings.map(canvas=>entityId(canvas.id));ids.splice(insertAt,0,entityId(movingCanvas.id));const selectedId=state.currentCanvas?.id||null;
  await withStructuralUndo(`Move canvas: ${movingCanvas.name}`,async()=>{await api(`/api/canvases/${movingCanvas.id}`,{method:'PATCH',body:JSON.stringify({parent_id:normalizedParent})});if(ids.length)await api('/api/canvases/reorder',{method:'POST',body:JSON.stringify({ids})})},{view:'canvas',canvasId:selectedId});
  await refresh(false);if(selectedId&&state.canvases.some(canvas=>entityId(canvas.id)===entityId(selectedId)))await selectCanvas(selectedId)
}
function removeCanvasOutdentZone(){$('#canvasOutdentDrop')?.remove()}
function showCanvasOutdentZone(movingCanvas){removeCanvasOutdentZone();if(!movingCanvas||movingCanvas.parent_id==null||!state.canvasRailExpanded)return;const rail=$('#canvasRail');if(!rail)return;const zone=document.createElement('div');zone.id='canvasOutdentDrop';zone.className='canvas-outdent-drop';zone.innerHTML='<span aria-hidden="true">←</span><b>{{i18n:dynamic.html.text.b.c4e5f750}}</b>';zone.ondragover=e=>{if(!state.dragCanvasId)return;e.preventDefault();e.stopPropagation();clearCanvasDropIndicator();zone.classList.add('ready');if(e.dataTransfer)e.dataTransfer.dropEffect='move'};zone.ondragleave=()=>zone.classList.remove('ready');zone.ondrop=async e=>{if(!state.dragCanvasId)return;e.preventDefault();e.stopPropagation();const moving=state.canvases.find(canvas=>entityId(canvas.id)===entityId(state.dragCanvasId)),parent=moving?state.canvases.find(canvas=>entityId(canvas.id)===entityId(moving.parent_id)):null;if(!moving||!parent)return;state.dragCanvasId=null;removeCanvasOutdentZone();clearCanvasDropIndicator();try{await moveCanvasToParent(moving,parent.parent_id,{afterCanvasId:parent.id})}catch(error){toast(error?.message||'Canvas could not be moved out.',4200);await refresh(false)}};rail.appendChild(zone)}
async function reorderCanvasSiblings(movingCanvas,targetCanvas,placeAfter){
  if(!movingCanvas||!targetCanvas||entityId(movingCanvas.id)===entityId(targetCanvas.id)||canvasParentKey(movingCanvas)!==canvasParentKey(targetCanvas))return;
  const parentKey=canvasParentKey(movingCanvas),siblings=state.canvases.filter(canvas=>canvasParentKey(canvas)===parentKey).sort((a,b)=>(+a.position||0)-(+b.position||0)||compareEntityIds(a.id,b.id)),ordered=siblings.filter(canvas=>entityId(canvas.id)!==entityId(movingCanvas.id)),targetIndex=ordered.findIndex(canvas=>entityId(canvas.id)===entityId(targetCanvas.id));
  if(targetIndex<0)return;ordered.splice(targetIndex+(placeAfter?1:0),0,movingCanvas);const ids=ordered.map(canvas=>entityId(canvas.id));if(ids.every((id,index)=>id===entityId(siblings[index]?.id)))return;
  const selectedId=state.currentCanvas?.id||null;
  await withStructuralUndo(`Reorder canvas: ${movingCanvas.name}`,()=>api('/api/canvases/reorder',{method:'POST',body:JSON.stringify({ids})}),{view:'canvas',canvasId:selectedId});
  await refresh(false);if(selectedId&&state.canvases.some(canvas=>entityId(canvas.id)===entityId(selectedId)))await selectCanvas(selectedId);
}
function renderCanvasRail(){
  hideCanvasDetailsHover();const box=$('#canvasRailItems');if(!box)return;box.innerHTML='';const byParent=new Map();for(const canvas of state.canvases){const key=canvasParentKey(canvas);if(!byParent.has(key))byParent.set(key,[]);byParent.get(key).push(canvas)}
  const renderLevel=(parentId,depth)=>{for(const canvas of byParent.get(parentId)||[]){const hasChildren=(byParent.get(canvas.id)||[]).length>0,collapsed=state.canvasCollapsed.has(canvas.id);const wrap=document.createElement('div');wrap.className='canvas-item-wrap';const row=document.createElement('div');row.className='canvas-item'+(state.currentCanvas?.id===canvas.id?' active':'');row.draggable=true;row.dataset.id=canvas.id;row.style.paddingLeft=`${Math.min(depth*12,72)}px`;row.innerHTML=`<span class="canvas-tree-toggle chapter-outline-toggle ${hasChildren?'':'placeholder'}" role="button" tabindex="${hasChildren?'0':'-1'}" aria-label="${escapeHtml(i18nText('canvas.toggle_named',{action:i18nSource(collapsed?'Expand':'Collapse'),name:canvas.name}))}" aria-expanded="${String(hasChildren&&!collapsed)}">${hasChildren?(collapsed?'▸':'▾'):''}</span><span class="canvas-grip chapter-grip" aria-hidden="true">⋮⋮</span><span class="canvas-item-initial">${escapeHtml(canvasRailLabel(canvas))}</span><span class="canvas-item-name">${escapeHtml(canvas.name)}</span><button type="button" class="canvas-item-more manuscript-item-more" aria-label="${escapeHtml(i18nText('canvas.actions_for',{name:canvas.name}))}"><span aria-hidden="true">⋮</span></button>`;row.onclick=e=>{if(e.target.closest('.canvas-tree-toggle:not(.placeholder),.canvas-item-more'))return;selectCanvas(canvas.id)};row.onmouseenter=()=>queueCanvasDetailsHover(canvas,row);row.onmouseleave=hideCanvasDetailsHover;row.oncontextmenu=e=>{e.preventDefault();openCanvasMenu(e,canvas)};row.querySelector('.canvas-item-more').onclick=e=>{e.preventDefault();e.stopPropagation();openCanvasMenu(e,canvas)};const toggle=row.querySelector('.canvas-tree-toggle:not(.placeholder)');if(toggle){const act=e=>{e.preventDefault();e.stopPropagation();if(collapsed)state.canvasCollapsed.delete(canvas.id);else state.canvasCollapsed.add(canvas.id);persistCanvasTree();renderCanvasRail()};toggle.onclick=act;toggle.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){act(e)}}}
    row.ondragstart=e=>{if(e.target.closest('.canvas-tree-toggle,.canvas-item-more')){e.preventDefault();return}state.dragCanvasId=entityId(canvas.id);row.classList.add('dragging');hideCanvasDetailsHover();clearCanvasDropIndicator();showCanvasOutdentZone(canvas);if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(canvas.id))}};
    row.ondragend=()=>{row.classList.remove('dragging');clearCanvasDropIndicator();removeCanvasOutdentZone();state.dragCanvasId=null};
    row.ondragover=e=>{if(!state.dragCanvasId||entityId(state.dragCanvasId)===entityId(canvas.id))return;const moving=state.canvases.find(item=>entityId(item.id)===entityId(state.dragCanvasId));if(!moving)return;const rect=row.getBoundingClientRect(),localY=e.clientY-rect.top,middle=localY>=rect.height*.28&&localY<=rect.height*.72,siblings=canvasParentKey(moving)===canvasParentKey(canvas);if(middle&&canNestCanvas(moving,canvas)){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';beginCanvasNestHover(row,moving,canvas);return}if(!siblings){clearCanvasNestHover();return}e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';clearCanvasDropIndicator();row.classList.add(localY>=rect.height/2?'drop-after':'drop-before')};
    row.ondragleave=e=>{if(e.relatedTarget&&row.contains(e.relatedTarget))return;if(canvasNestHoverId===entityId(canvas.id)&&!canvasNestReadyId)clearCanvasNestHover()};
    row.ondrop=async e=>{if(!state.dragCanvasId||entityId(state.dragCanvasId)===entityId(canvas.id))return;const moving=state.canvases.find(item=>entityId(item.id)===entityId(state.dragCanvasId));if(!moving)return;e.preventDefault();e.stopPropagation();const rect=row.getBoundingClientRect(),localY=e.clientY-rect.top,middle=localY>=rect.height*.28&&localY<=rect.height*.72,nestReady=middle&&canvasNestReadyId===entityId(canvas.id)&&canNestCanvas(moving,canvas);clearCanvasDropIndicator();removeCanvasOutdentZone();state.dragCanvasId=null;try{if(nestReady){await moveCanvasToParent(moving,canvas.id);state.canvasCollapsed.delete(entityId(canvas.id));persistCanvasTree();renderCanvasRail()}else if(canvasParentKey(moving)===canvasParentKey(canvas)){await reorderCanvasSiblings(moving,canvas,localY>=rect.height/2)}}catch(error){toast(error?.message||'Canvas could not be moved.',4200);await refresh(false)}};
    wrap.appendChild(row);box.appendChild(wrap);if(hasChildren&&!collapsed)renderLevel(canvas.id,depth+1)}};renderLevel(0,0);
  appendCollectionQuickAdd(box,i18nSource('Add Canvas'),()=>openNewCanvasModal(null));
  const empty=!state.canvases.length;$('#canvasEmpty').classList.toggle('hidden',!empty);$('#canvasSpace').classList.toggle('hidden',empty);const canvasDetails=$('#editCanvasDetailsBtn');if(empty){state.currentCanvas=null;state.canvasNodes=[];state.canvasEdges=[];$('#canvasName').value='';if(canvasDetails){canvasDetails.classList.add('hidden');canvasDetails.disabled=true}}else if(canvasDetails){canvasDetails.classList.remove('hidden');canvasDetails.disabled=false};
}
$('#addCanvas').onclick=openCanvasCollectionMenu;$('.canvas-rail-head').oncontextmenu=openCanvasCollectionMenu;$('#emptyCreateCanvas').onclick=()=>openNewCanvasModal(null);

function nextCanvasName(){const used=new Set(state.canvases.map(c=>(c.name||'').trim().toLocaleLowerCase()));let n=1,label=i18nSource('Canvas');while(used.has(`${label} ${n}`.toLocaleLowerCase())||used.has(`canvas ${n}`))n++;return `${label} ${n}`} 
function openNewCanvasModal(parentId=null){
  closeCanvasPanel();
  const typeOptions=[
    ['blank','Blank','Start with an empty board and add Cards as you need them.'],
    ['developmental','Developmental','Reorder Chapters or Scenes visually, then preview the exact manuscript change before applying it.'],
  ];
  const manuscript=state.documents.find(doc=>doc.is_manuscript),writtenScenes=state.scenes.filter(scene=>(!manuscript||entityId(scene.tab_id)===entityId(manuscript.id))&&Number(scene.block_count||0)>0),canUseScenes=writtenScenes.length>0;
  showModal('New Canvas',`<div class="canvas-create-form">
    <div class="field"><label>{{i18n:dynamic.html.text.label.450ca425}}</label><input id="newCanvasName" value="${escapeHtml(nextCanvasName())}" autofocus></div>
    <div class="field"><label>{{i18n:dynamic.html.text.label.40a966a4}} <span class="optional-label">{{i18n:dynamic.html.text.span.196b480c}}</span></label><textarea id="newCanvasDescription" rows="3" placeholder="{{i18n:dynamic.html.attr.placeholder.26b5b541}}"></textarea></div>
    <div class="field"><label>{{i18n:dynamic.html.text.label.215a121d}}</label><input id="newCanvasType" type="hidden" value="blank"><div class="canvas-create-types">${typeOptions.map(([value,label,description],index)=>`<button type="button" class="canvas-create-type ${index===0?'active':''}" data-canvas-type="${value}" aria-pressed="${index===0?'true':'false'}"><b>${escapeHtml(i18nSource(label))}</b><span>${escapeHtml(i18nSource(description))}</span></button>`).join('')}</div></div>
    <div id="developmentalScopeField" class="field canvas-developmental-scope hidden"><label>{{i18n:dynamic.html.text.label.29e36c9e}}</label><input id="newCanvasDevelopmentalScope" type="hidden" value="chapters"><div class="canvas-scope-options"><button type="button" class="canvas-scope-option active" data-developmental-scope="chapters" aria-pressed="true"><b>{{i18n:dynamic.html.text.b.ac32119a}}</b><span>{{i18n:dynamic.html.text.span.2c11496b}}</span></button><div class="canvas-scope-tooltip" ${canUseScenes?'':`title="{{i18n:dynamic.html.attr.title.3f137680}}"`}><button type="button" class="canvas-scope-option ${canUseScenes?'':'disabled'}" data-developmental-scope="scenes" aria-pressed="false" aria-disabled="${canUseScenes?'false':'true'}"><b>{{i18n:dynamic.html.text.b.de3f8328}}</b><span>${escapeHtml(i18nSource(canUseScenes?'One Card per written Main Manuscript Scene.':'Create a Scene in the Main Manuscript first.'))}</span></button></div></div></div>
    <div class="field"><label>{{i18n:dynamic.html.text.label.685d9216}}</label><select id="newCanvasParent"><option value="">{{i18n:dynamic.html.text.option.e9410c1e}}</option>${state.canvases.map(c=>`<option value="${c.id}" ${c.id===parentId?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div>
  </div>`,`<button id="cancelNewCanvas">{{i18n:dynamic.html.text.button.92113f72}}</button><button id="createCanvasConfirm">{{i18n:dynamic.html.text.button.9b36bca2}}</button>`);
  const typeInput=$('#newCanvasType'),scopeInput=$('#newCanvasDevelopmentalScope'),scopeField=$('#developmentalScopeField');
  const syncType=()=>scopeField.classList.toggle('hidden',typeInput.value!=='developmental');
  $$('[data-canvas-type]').forEach(button=>button.onclick=()=>{typeInput.value=button.dataset.canvasType;$$('[data-canvas-type]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',active?'true':'false')});syncType()});
  $$('[data-developmental-scope]').forEach(button=>button.onclick=()=>{if(button.getAttribute('aria-disabled')==='true')return;scopeInput.value=button.dataset.developmentalScope;$$('[data-developmental-scope]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',active?'true':'false')})});
  $('#cancelNewCanvas').onclick=()=>closeModal();
  const create=async()=>{const name=$('#newCanvasName').value.trim(),canvas_type=typeInput.value,developmental_scope=canvas_type==='developmental'?scopeInput.value:'chapters',parent_id=$('#newCanvasParent').value?entityId($('#newCanvasParent').value):null;if(!name){$('#newCanvasName').focus();return}const button=$('#createCanvasConfirm');button.disabled=true;button.textContent=i18nSource('Creating…');try{let canvas;await withStructuralUndo(`Create canvas: ${name}`,async()=>{canvas=await api('/api/canvases',{method:'POST',body:JSON.stringify({name,description:$('#newCanvasDescription').value,canvas_type,developmental_scope,parent_id})})},{view:'canvas',undoScope:'canvas-tree'});closeModal(false);state.canvases.push(canvas);renderCanvasRail();setView('canvas');await selectCanvas(canvas.id)}catch(error){button.disabled=false;button.textContent=i18nSource('Create Canvas');toast(error.message||'Canvas could not be created.')}};
  $('#createCanvasConfirm').onclick=create;
  $('#newCanvasName').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();create()}};
  syncType();queueMicrotask(()=>$('#newCanvasName')?.select());
}
function openCanvasPanel(title,html){canvasPanelEpoch++;$('#canvasPanelTitle').textContent=i18nSource(title);$('#canvasPanelBody').innerHTML=html;$('#canvasToolPanel').classList.remove('hidden');if(title!=='Structure'){$('#canvasStructureBtn')?.classList.remove('active');$('#canvasStructureBtn')?.setAttribute('aria-pressed','false')}return canvasPanelEpoch}
function closeCanvasPanel(){canvasPanelEpoch++;hideCardDisplayTip();hideStructurePanelHover();$('#canvasToolPanel').classList.add('hidden');$('#canvasStructureBtn')?.classList.remove('active');$('#canvasStructureBtn')?.setAttribute('aria-pressed','false')}
$$('[data-close-canvas-panel]').forEach(b=>b.onclick=closeCanvasPanel);
function configureCanvas(canvas){showModal('Configure Canvas',`<div class="field"><label>{{i18n:dynamic.html.text.label.450ca425}}</label><input id="canvasConfigName" value="${escapeHtml(canvas.name)}"></div><div class="field"><label>{{i18n:dynamic.html.text.label.40a966a4}}</label><textarea id="canvasConfigDescription" rows="4">${escapeHtml(canvas.description||'')}</textarea></div>`,`<button id="saveCanvasConfig">{{i18n:dynamic.html.text.button.9faf5fce}}</button>`);$('#saveCanvasConfig').onclick=async()=>{const name=$('#canvasConfigName').value.trim();if(!name)return;await withStructuralUndo(`Configure canvas: ${canvas.name}`,()=>api(`/api/canvases/${canvas.id}`,{method:'PATCH',body:JSON.stringify({name,description:$('#canvasConfigDescription').value})}),{view:'canvas',canvasId:canvas.id});dismissModalTree();await refresh(false);if(state.currentCanvas?.id===canvas.id)await selectCanvas(canvas.id)}}
async function renameCanvas(canvas){configureCanvas(canvas)}
async function deleteCanvas(canvas){if(!await confirmDialog('Delete Canvas',i18nText('confirm.delete_canvas',{name:canvas.name}),{confirmLabel:'Delete canvas',danger:true}))return;await withStructuralUndo(`Delete canvas: ${canvas.name}`,()=>api(`/api/canvases/${canvas.id}`,{method:'DELETE'}),{view:'canvas',canvasId:canvas.parent_id||null});const wasOpen=state.currentCanvas?.id===canvas.id;await refresh(false);if(wasOpen){const next=state.canvases.find(c=>c.parent_id===canvas.parent_id)||state.canvases[0];if(next)await selectCanvas(next.id);else renderCanvasRail()}toast('Canvas deleted')}

function canvasViewportKey(id){return `canvas-viewport-${id}`}
function updateCanvasModeUI(){
  const effective=state.canvasSpaceHeld?'hand':state.canvasMode;
  const hand=$('#canvasHandMode'),pointer=$('#canvasPointerMode'),stage=$('#canvasStage');
  hand?.classList.toggle('active',effective==='hand');pointer?.classList.toggle('active',effective==='pointer');
  hand?.setAttribute('aria-pressed',String(effective==='hand'));pointer?.setAttribute('aria-pressed',String(effective==='pointer'));
  stage?.classList.toggle('hand-mode',effective==='hand');stage?.classList.toggle('pointer-mode',effective==='pointer');stage?.classList.toggle('space-pan',state.canvasSpaceHeld);
}
async function setCanvasMode(mode,{persist=true}={}){if(!['hand','pointer'].includes(mode))return;state.canvasMode=mode;updateCanvasModeUI();if(persist)queueCanvasViewportPersist()}
const CANVAS_TEXT_SIZE_DEFAULT=20.5,CANVAS_TEXT_SIZE_MIN=11,CANVAS_TEXT_SIZE_MAX=28;
function configuredCanvasTextSize(){const pt=Number(state.canvasConfig?.node_typography?.content_font_size_pt);return Number.isFinite(pt)?Math.round((pt*96/72)*2)/2:CANVAS_TEXT_SIZE_DEFAULT}
function normalizeCanvasTextSize(value){const size=Number(value);if(!Number.isFinite(size))return CANVAS_TEXT_SIZE_DEFAULT;return Math.max(CANVAS_TEXT_SIZE_MIN,Math.min(CANVAS_TEXT_SIZE_MAX,Math.round(size*2)/2))}
